from pypdf import PdfReader

reader = PdfReader("sc100-blank.pdf")
fields = reader.get_fields()

if fields:
    for field_name, value in fields.items():
        if "PlaintiffName1" in field_name:
            print(f"Field: {field_name}")
            print(f"  T: {value.get('/T')}")

from pypdf import PdfReader

reader = PdfReader("sc100-filled.pdf")
fields = reader.get_fields()

expected_values = {
    'PlaintiffName1[0]': 'Joyce He',
    'PlaintiffPhone1[0]': '412-588-6066',
    'PlaintiffAddress1[0]': '655 S Fair Oaks Ave',
    'DefendantName1[0]': 'Zhi Chen',
    'Checkbox50[0]': '/1',
    'Checkbox60[1]': '/2',
    'Checkbox61[1]': '/2',
    'Checkbox62[1]': '/2',
    'Checkbox63[1]': '/2',
    'Checkbox5cb[0]': '/1'
}

print("Verifying fields...")
if fields:
    for field_name, value in fields.items():
        # Check if any of our expected keys are in the field name (since field name is full path)
        for key, expected in expected_values.items():
            if field_name.endswith(key):
                actual = value.get('/V')
                if actual == expected:
                    print(f"MATCH: {key} = {actual}")
                else:
                    print(f"MISMATCH: {key} = {actual} (Expected: {expected})")
else:
    print("No fields found in filled PDF.")
